begin;
set local s1.tap='off';
\ir s3_fixture.sql
update public.rooms set stage='confirmed',appointment_confirmed_at=clock_timestamp(),appointment_confirmed_by=owner_id where id=pg_temp.s3_room();
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
insert into s4_data values('pending_before_bill',public.request_room_owner_transfer_v1(pg_temp.s3_room(),'10000002-0000-4000-8000-000000000002',true,pg_temp.s3_rev(),gen_random_uuid()));
insert into s4_data values('bill',to_jsonb(public.create_room_settlement_v2(pg_temp.s3_room(),'Synthetic bill',2000,'Synthetic','0000','Synthetic')));
reset role;
select pg_temp.check((select status='expired' and terminal_reason='settlement_started' from private.s3_transfer_requests where id=(select (v->>'transfer_id')::uuid from s4_data where k='pending_before_bill')),'settlement expires pending in the same transaction before bill lock');
select pg_temp.check((select count(*)=2 from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='bill')),'settlement snapshot uses actual current members');
set local role authenticated;
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.leave_room_member_v1(pg_temp.s3_room(),pg_temp.s3_rev(),gen_random_uuid())$q$)='S3001','room unfinished bill blocks ordinary leave');
select public.set_settlement_completed(id,true) from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='bill') and profile_id=auth.uid();
select pg_temp.check((public.get_room_lifecycle_v1(pg_temp.s3_room())->>'can_leave')::boolean,'done member may leave once every recipient completes');
reset role;
create temporary table s3_snapshot_before as select to_jsonb(b) bill,(select jsonb_agg(to_jsonb(m) order by m.id) from public.dutch_pay_members m where m.bill_id=b.id) recipients from public.dutch_pay_bills b where b.id=(select (v#>>'{}')::uuid from s4_data where k='bill');
set local role authenticated;
select public.leave_room_member_v1(pg_temp.s3_room(),pg_temp.s3_rev(),gen_random_uuid());
select pg_temp.check((public.get_settlement_payment_details((select (v#>>'{}')::uuid from s4_data where k='bill'))->>'status')='completed','departed recipient retains S1 snapshot access');
reset role;
select pg_temp.check((select bill=to_jsonb(b) and recipients=(select jsonb_agg(to_jsonb(m) order by m.id) from public.dutch_pay_members m where m.bill_id=b.id) from s3_snapshot_before,public.dutch_pay_bills b where b.id=(select (v#>>'{}')::uuid from s4_data where k='bill')),'leave does not mutate bill amount, denominator, payment state or recipients');
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
insert into s4_data values('restart_bill',to_jsonb(public.create_room_settlement_v2(pg_temp.s3_room(),'New round',1000,'Synthetic','0000','Synthetic')));
reset role;
select pg_temp.check((select count(*)=1 from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='restart_bill')),'new round excludes departed member without rewriting historical snapshot');
select pg_temp.check((select expires_at<=appointment_confirmed_at+interval '30 days' from public.rooms where id=pg_temp.s3_room()),'restart retains immutable S4 thirty-day cap');
update public.rooms set expires_at=clock_timestamp()-interval '1 second' where id=pg_temp.s3_room();
select private.cleanup_expired_rooms_v1();
select pg_temp.check((select room_id is null from public.dutch_pay_bills where id=(select (v#>>'{}')::uuid from s4_data where k='bill')),'expiry detaches bill rather than deleting payment evidence');
set local role authenticated;
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check((public.get_settlement_payment_details((select (v#>>'{}')::uuid from s4_data where k='bill'))->>'status')='completed','detached historical recipient still has access');
reset role;
update public.rooms set stage='confirmed',appointment_confirmed_at=clock_timestamp(),appointment_confirmed_by=owner_id where id='24000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
insert into s4_data values('expired_payment_bill',to_jsonb(public.create_room_settlement_v2('24000000-0000-4000-8000-000000000001','Expired payment',2000,'Synthetic','0000','Synthetic')));
reset role;
update public.rooms set expires_at=clock_timestamp()-interval '1 second' where id='24000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select public.set_settlement_completed(id,true) from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='expired_payment_bill') and profile_id=auth.uid();
reset role;
select pg_temp.check((select expires_at<=clock_timestamp() from public.rooms where id='24000000-0000-4000-8000-000000000001'),'late recipient payment never resurrects expired room access');
select pg_temp.check((select is_completed from public.dutch_pay_members where bill_id=(select (v#>>'{}')::uuid from s4_data where k='expired_payment_bill') and profile_id='10000002-0000-4000-8000-000000000002'),'late payment still completes its fixed recipient snapshot');
rollback;
